<?php require __DIR__.'/../bootstrap.php';require_login();if(plan_limit_reached('notes')){flash('error','Your current plan limit has been reached. Upgrade to continue.');redirect('/pricing/');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('INSERT INTO notes(user_id,title,content,is_pinned,created_at,updated_at) VALUES(?,?,?,?,NOW(),NOW())')->execute([current_user()['id'],post('title'),post('content'),post('pinned')?1:0]);increment_counter('notes_created_counter'); log_event('notes_created',(int)current_user()['id']); redirect('/notes/');}$title='New Note';require __DIR__.'/../includes/header.php';?><form class="card form-card" method="post"><?=csrf_field()?><label>Title<input name="title" required></label><label>Content<textarea name="content" rows="16"></textarea></label><label class="check"><input type="checkbox" name="pinned" value="1"> Pin note</label><button class="btn">Save Note</button><p><a class="btn secondary small" href="/ai/?prompt=Note%20assist%3A%20help%20me%20improve%20this%20note">✨ AI Assist</a></p></form><?php require __DIR__.'/../includes/footer.php'; ?>